import 'package:flutter/material.dart';import '../services/global_tours_service.dart';
class HospitalityScreen extends StatelessWidget{const HospitalityScreen({super.key,required this.user});final Map<String,dynamic> user;@override Widget build(BuildContext c)=>FutureBuilder(future:Future.wait([GlobalToursService().list('hotels','${user['tenantId']??''}'),GlobalToursService().list('accommodations','${user['tenantId']??''}')]),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final all=(s.data as List<List>).expand((x)=>x).toList();return ListView(padding:const EdgeInsets.all(16),children:[Text('Hospitality & Accommodation',style:Theme.of(c).textTheme.headlineSmall),...all.map((x)=>Card(child:ListTile(leading:const Icon(Icons.hotel),title:Text(x.name),subtitle:Text(x.description.isEmpty?x.status:x.description))))]);}}
